INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-valtozas', 'Változás varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'wrapper', 'Part 14', '{"id": "jel-varazsjel-valtozas", "name": "Változás varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "wrapper", "baseMp": 0, "factor": 3, "wraps": [{"school": "anyagi", "subgroup": "termeszetes", "label": "Természetes anyagi mágia"}]}, "inputs": [], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nMinden a Természeti Anyag Mágiájának fejezete alá tartozó hatás leírható Változás Varázsjellel. A varázsjelet arra a tárgyra kell rajzolni, amelyet a varázsjellel a varázsló megváltoztatni kíván, hatása ellen nem véd a Személyes Aura sem. Az adott hatás nem ér véget a mozaiknál feltüntetett időtartam lejártával, hanem mindaddig érvényesül, ameddig a tárgyon a varázsjel töretlen. A Változás Varázsjel megrajzolása háromszor annyi Mp-be kerül, mint a hasonló varázslat mozaik, ám erőssége ugyanannyi marad.", "source": "Part 14", "requires": [{"school": "anyagi", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-zona', 'Zóna varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-varazsjel-zona", "name": "Zóna varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "flat", "baseMp": 25}, "inputs": [], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nA zóna varázsjel körüli 20 láb sugarú gömb a varázsló zónájának számít, akárcsak a teste körüli hasonló méretű terület. Vagyis, ahol ezt a varázsjelet a varázsló elhelyezi, ott újabb Zóna jön létre, amelyen belül majdnem úgy varázsolhat távolbahatás nélkül is, ahogyan azt a teste körüli zónában teheti. A különbség csupán annyi, hogy a zóna varázsjelen keresztül végrehajtott varázslatok varázslási ideje minden esetben +1 körrel nő, s az eredeti mannapont igényéhez +5 mp járul.\n\nA varázslók éppen ezért gyakran helyeznek el zóna varázsjelet olyan helyeken, ahová később varázsolni kívánnak. Nem egyszer apróbb tárgyakra írják, és azokat szolgákkal vitetik el a világ azon távoli pontjaira, ahová mágikus befolyásukat kiterjeszteni készülnek.\n\nA Zóna varázsjel másik felmérhetetlenül hasznos tulajdonsága, hogy lehetővé teszi a varázsló számára, hogy arra a helyre teleportáljon, vagy kaput nyisson, ahol a jel található.\n\nMinden zóna varázsjel egyéni, azaz minden varázslónak saját jele van – ami az avatott szem fel is ismerheti. Minden varázsló csak saját zóna varázsjelét használhatja távolba varázslásra és térmágiára.\n\nHátránya, hogy a tárgy szimpátia viszonyban áll a varázslóval, így ellenséges szándékú varázsló kezében veszélyessé lehet.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-szemelyes-aura', 'Személyes aura varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-varazsjel-szemelyes-aura", "name": "Személyes aura varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "flat", "baseMp": 40}, "inputs": [{"id": "effectType", "label": "Hatás", "type": "choice", "values": ["asztral", "mental"], "labels": {"asztral": "Asztrálmágia", "mental": "Mentálmágia"}, "requires": {"asztral": [{"school": "asztral", "tier": 2}], "mental": [{"school": "mental", "tier": 2}]}}], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nA tárgy, amelyen a varázsló elhelyezi a varázsjelet, Személyes Aurájának védelme alá kerül. Ez azt jelenti, hogy attól kezdve az aura védelme az adott tárgyra is kiterjed. Természetesen a varázsló nem csak saját, hanem valaki más Személyes Aurájának is részévé tehet ily módon bármely holmit, ehhez az illetőnek magának kell a varázsjelbe mágikus rúnákkal beleírnia a nevét. Ami persze okozhat némi nehézséget, hiszen a rúnák pontos leírását egyedül a varázslók tanulják. Nem varázsló karakternek ahhoz, hogy saját nevét rúnákkal képes legyen hibátlanul leírni, 3 hétig minden nap legalább két órát kell gyakorolnia.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-magikus-aura', 'Mágikus aura varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-varazsjel-magikus-aura", "name": "Mágikus aura varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "flat", "baseMp": 33}, "inputs": [], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nA tárgy, amelyre a varázsló felírja a Mágikus Aura Varázsjelét, attól kezdve mágikusnak számít, miáltal nem hat rá a Természeti Anyag Mágiája. Rúnamágiával készített varázstárgyaknál a Mágikus Aura Varázsjel terjeszti ki a rúna mágikus hatását az adott tárgyra. (ld. Varázstárgyak)", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-lelekcsapda', 'Lélekcsapda varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-varazsjel-lelekcsapda", "name": "Lélekcsapda varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 3}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "flat", "baseMp": 35}, "inputs": [], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nLásd: Nekromancia (kell hozzá Nekromancia 2. fok).", "source": "Part 14", "requires": [{"school": "nekromancia", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-kisugarzo', 'Kisugárzó varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'wrapper', 'Part 14', '{"id": "jel-varazsjel-kisugarzo", "name": "Kisugárzó varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 3}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "byChoice", "input": "variant", "values": {"touch": {"kind": "touch"}, "pass": {"kind": "feet", "value": 1}}}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "wrapper", "input": "variant", "baseMpByValue": {"touch": 20, "pass": 30}, "factor": 1}, "inputs": [{"id": "variant", "label": "Válfaj", "type": "choice", "values": ["touch", "pass"], "labels": {"touch": "Megérintőre hat (20 MP)", "pass": "Elhaladókra hat, 1 láb (30 MP)"}}], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nA végrehajtó varázskör ikertestvére; hatása és működése is ahhoz hasonló. Két válfaja ismeretes: az elsőnél a beleírt varázslat arra hat, aki a varázsjelet megérinti, a másodiknál a varázsjel előtt karnyújtásnyira (1 láb) távolságon belül elhaladókra – válogatás nélkül. A hatás megnyilvánulása és az érintettek elleni hatékonysága a varázsjelbe írt varázslat természetétől és erősségétől függ (pl. a kicsapó tűznyíl nem feltétlenül találja el az áldozatot).\n\nAz első változat 20 mp, plusz amibe a varázslat kerül, a második 10 mp-vel több.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-szimpatia', 'Szimpátia varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-varazsjel-szimpatia", "name": "Szimpátia varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 6}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": null}, "cost": {"pattern": "flat", "baseMp": 20}, "inputs": [], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nJelpár, amely tárgy-tárgy szimpátiát hoz létre két tárgy között, melyekre írják őket. Ha bármelyik rajzolat megsérül, a szimpátia azonnal megszűnik.", "source": "Part 14", "requires": [{"school": "szimpatikus", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-kemszem', 'Kémszem varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'lookup', 'Part 14', '{"id": "jel-varazsjel-kemszem", "name": "Kémszem varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 10}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "byInput"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": null}, "cost": {"pattern": "lookup", "input": "distanceFt", "table": [{"fromM": 0, "toM": 10, "mp": 55}, {"fromM": 11, "toM": 39, "mp": 60}, {"fromM": 40, "toM": 99, "mp": 68}, {"fromM": 100, "toM": 999, "mp": 75}]}, "inputs": [{"id": "distanceFt", "label": "Legnagyobb távolság a jel és a bélyeg között", "type": "number", "unit": "láb", "integer": true, "min": 0}], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nJelpár, amely egymással szimpátia viszonyban álló varázsjelből és bélyegből áll. Az első bárhol, bármilyen tárgyon elhelyezhető, míg a második arra a személyre írandó, aki a varázsjellel látni fog.\n\nA bélyeg viselője – ha akarja – képes a varázsjellel úgy látni, mintha az saját szeme lenne. Ilyenkor saját szemével természetesen nem lát. Ha valaki úgy rajzolja fel a bélyeget, hogy az egyszerre több varázsjellel is kapcsolatban áll, tetszése szerint válogathat azok között, egyikről a másikra váltva egymás után több helyszínt is szemmel tarthat. Fontos megjegyezni, hogy a kémszem nem forgatható, azaz egyetlen, meghatározott irányba mered. Forgatásáról, mozgatásáról más varázslattal, netán kahrei mechanikával szükséges gondoskodni.\n\nA rajzolat felírásának mp igénye a bélyeg és a varázsjel maximális távolságától függ. Ha ennél távolabb kerülnek egymástól, a szimpátia viszony szünetel, így a kémszem ideiglenesen megvakul, s csak akkor használható újból, ha ismét hatótávba kerül.\n\nHatótáv – Mp igény:\n0–10 láb – 55 mp\n11–39 láb – 60 mp\n40–99 láb – 68 mp\n100–999 láb – 75 mp\nEnnél nagyobb távolságra nem alkalmazható.\n\nA fent feltüntetett Mana-pontok a teljes jelpárra vonatkoznak; a szimpátia viszony miatt közös transzban kell megrajzolni őket. Több varázsjel egy bélyeghez csatlakoztatása esetén a bélyeget is minden alkalommal újra kell rajzolni, bár vonalai tökéletesen fedhetik a korábban felírt bélyegekét. Az újabb és újabb jelpárok természetesen már újabb és újabb transzban is megalkothatóak – így minden pár felrajzolása után nyílik mód mana-pont gyűjtésre.\n\nA kémszem addig működőképes, ameddig mindkét rajzolat töretlen.", "source": "Part 14", "requires": [{"school": "szimpatikus", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-tergat', 'Térgát varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'linear', 'Part 14', '{"id": "jel-varazsjel-tergat", "name": "Térgát varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "byInput"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 3, "e": 1}}, "cost": {"pattern": "linear", "input": "radiusM", "baseMp": 3, "freeUnits": 1, "mpPerUnit": 1}, "inputs": [{"id": "radiusM", "label": "Sugár", "type": "number", "unit": "m", "integer": true, "min": 1}], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nA Térgát varázsjel Ynev várainak, palotáinak, erősségeinek mindennapos kelléke, a rúnatornyok leggyakoribb jele. Az adott területet belül gátat szab minden térmágiának: a területről és a területre teleportálni, távolbahatni, térkaput nyitni lehetetlen, hacsak a térmágia erőssége meg nem haladja a varázsjelét. Alapterület, amiben gátol: egy 1 méter sugarú gömb, amit méterenként 1 MP-ért lehet növelni.", "source": "Part 14", "requires": [{"school": "ter", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-tercsapda', 'Tércsapda varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'linear', 'Part 14', '{"id": "jel-varazsjel-tercsapda", "name": "Tércsapda varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "byInput"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 3, "e": 1}}, "cost": {"pattern": "linear", "input": "radiusM", "baseMp": 8, "freeUnits": 1, "mpPerUnit": 1}, "inputs": [{"id": "radiusM", "label": "Sugár", "type": "number", "unit": "m", "integer": true, "min": 1}], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nA Tércsapda varázsjel a Térgát varázsjel különleges változata. Hatóterületén nem gátat szab a térmágiának, hanem a varázsjelhez vonzza. Minden térmágikus hatás a varázsjelen ill. annak közvetlen szomszédságában jön létre.", "source": "Part 14", "requires": [{"school": "ter", "tier": 3}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-tapadas', 'Tapadás varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'perMass', 'Part 14', '{"id": "jel-varazsjel-tapadas", "name": "Tapadás varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"kor": 2}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "perMass", "rate": {"mp": 1, "massG": 5000}}, "inputs": [{"id": "weightKg", "label": "Tartott súly", "type": "number", "unit": "kg"}], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nVarázsjel pár, amelyet két különálló tárgyon kell elhelyezni: a két jel tükörképe egymásnak, pontosan egymáshoz illesztve összetapadnak. Minél erősebb a beléjük foglalt mágia, annál nehezebben választhatóak szét, azaz annál nagyobb a súly, amelynek megtartására alkalmasak. Szét lehet választani őket erővel, de újra összetapadnak, ha a jelek töretlenek.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-varazsjel-forgas', 'Forgás varázsjel', 'jelmagia', 'varazsjelek', 2, 'complete', 'perMass', 'Part 14', '{"id": "jel-varazsjel-forgas", "name": "Forgás varázsjel", "school": "jelmagia", "subgroup": "varazsjelek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"kor": 2}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "drawing"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": 1, "step": {"mp": 1, "e": 1}}, "cost": {"pattern": "perMass", "rate": {"mp": 1, "massG": 5000}, "multiplierInput": "speed"}, "inputs": [{"id": "weightKg", "label": "Forgatott súly", "type": "number", "unit": "kg"}, {"id": "speed", "label": "Sebesség (szorzó)", "type": "number", "unit": "×", "integer": true, "min": 1}], "effect": "Soha nem nagyobb egy ezüstpénznél.\n\nA tapadáshoz hasonló jel pár, ám az összeillesztett tárgyak, a rögzítetlen vagy kisebb súlyú, a varázsjelek képezte tengely körül forognak. A jelek kicsik, de a tárgy lehet nagyobb; a forgás tengelye ott van, ahol a két jel találkozik. Egy tenyérnyi korong 5 szegmens alatt tesz meg egy teljes kört; ha a teljes mp igényt megduplázod, a sebesség duplázódik, háromszorosával triplázódik stb.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-szimbolum-asztral', 'Asztrálszimbólum', 'jelmagia', 'szimbolumok', 2, 'complete', 'wrapper', 'Part 14', '{"id": "jel-szimbolum-asztral", "name": "Asztrálszimbólum", "school": "jelmagia", "subgroup": "szimbolumok", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 30}}}, "duration": {"kind": "undefined"}, "range": {"kind": "sight"}, "resistance": {"kind": "school", "school": "asztral"}, "power": null, "cost": {"pattern": "wrapper", "baseMp": 0, "factor": 1, "keepsDuration": true, "wraps": [{"school": "asztral", "label": "Asztrál mágia"}]}, "inputs": [], "effect": "Embermagasságnál nagyobb mágikus jel vagy felirat.\n\nAz Asztrál és Mentál mágiáról szóló fejezetben leírt összes varázslat felrajzolható ebben a formában. Hatásukat arra fejtik ki, aki megpillantja őket – ám az illető csak akkor válik a varázslat áldozatává, ha Mágia ellenállását elvéteti. Egy szimbólum elkészítése annyi mp-be kerül, amennyibe a belefoglalt varázslat.\n\nAz asztrálszimbólumok akkor fejtik ki hatásukat, amikor az áldozat megpillantja őket. Szimbólumként bármely az asztrál fejezetben leírt varázslat felírható. Ennek Mp igénye annyi, amennyi az azonos asztrál varázslaté és erőssége, valamint időtartama is azével egyenlő.\n\nAz asztrál szimbólumok ellen az áldozat dobhat asztrális mágiaellenállást, melynek sikere esetén mentesül a szimbólum hatása alól.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-szimbolum-mental', 'Mentálszimbólum', 'jelmagia', 'szimbolumok', 2, 'complete', 'wrapper', 'Part 14', '{"id": "jel-szimbolum-mental", "name": "Mentálszimbólum", "school": "jelmagia", "subgroup": "szimbolumok", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 35}}}, "duration": {"kind": "undefined"}, "range": {"kind": "sight"}, "resistance": {"kind": "school", "school": "mental"}, "power": null, "cost": {"pattern": "wrapper", "baseMp": 0, "factor": 1, "keepsDuration": true, "wraps": [{"school": "mental", "label": "Mentál mágia"}]}, "inputs": [], "effect": "Embermagasságnál nagyobb mágikus jel vagy felirat.\n\nAz Asztrál és Mentál mágiáról szóló fejezetben leírt összes varázslat felrajzolható ebben a formában. Hatásukat arra fejtik ki, aki megpillantja őket – ám az illető csak akkor válik a varázslat áldozatává, ha Mágia ellenállását elvéteti. Egy szimbólum elkészítése annyi mp-be kerül, amennyibe a belefoglalt varázslat.\n\nA mentál szimbólumok az asztrál szimbólumokhoz hasonlóak. Hatásukat arra fejtik ki, aki megpillantja őket. Szimbólumként bármely mentál varázslat felírható, ennek mp igénye annyi, amennyi az azonos hatású mentál varázslaté, ugyanez igaz az erősségre és időtartamra is.\n\nA mentálszimbólumok ellen az áldozat dobhat mentális ellenállást, melynek sikere esetén mentesül a szimbólum hatása alól.", "source": "Part 14"}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-belyeg-asztral', 'Asztrálbélyeg', 'jelmagia', 'belyegek', 2, 'complete', 'wrapper', 'Part 14', '{"id": "jel-belyeg-asztral", "name": "Asztrálbélyeg", "school": "jelmagia", "subgroup": "belyegek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "body"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": null, "step": null, "infinite": true}, "cost": {"pattern": "wrapper", "baseMp": 0, "factor": 1, "innerE": 15, "wraps": [{"school": "asztral", "label": "Asztrál mágia"}]}, "inputs": [], "effect": "Néhány centiméter átmérőjű jel, a megbélyegzett testén. Hatásukat arra fejtik ki, akinek a testén a varázsló elhelyezi őket. Az alany egészen addig áldozata a bélyeg hordozta mágiának, ameddig az el nem távolíttatik a testéről. A bélyegek oly erősen sugározzák a beléjük foglalt mágikus hatást, hogy velük szemben mágiaellenállásnak helye nincs.\n\nAz asztrálbélyegek alkalmasak arra, hogy viselőjüket az adott asztrálmágia hatása alá helyezzék. Transzban tudja az áldozat testére rajzolni. Annyi manna, amennyibe az adott varázslat kerülne 15 E erősség esetén. Viszont nincs ellene ellenállás. Az áldozat adott esetben letörölheti magáról.\n\nAsztrálbélyeg esetén a jeleknek tartalmazniuk kell az érzelem irányát is.", "source": "Part 14", "requires": [{"school": "asztral", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-belyeg-mental', 'Mentálbélyeg', 'jelmagia', 'belyegek', 2, 'complete', 'wrapper', 'Part 14', '{"id": "jel-belyeg-mental", "name": "Mentálbélyeg", "school": "jelmagia", "subgroup": "belyegek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "body"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": null, "step": null, "infinite": true}, "cost": {"pattern": "wrapper", "baseMp": 0, "factor": 1, "innerE": 20, "wraps": [{"school": "mental", "label": "Mentál mágia"}]}, "inputs": [], "effect": "Néhány centiméter átmérőjű jel, a megbélyegzett testén. Hatásukat arra fejtik ki, akinek a testén a varázsló elhelyezi őket. Az alany egészen addig áldozata a bélyeg hordozta mágiának, ameddig az el nem távolíttatik a testéről. A bélyegek oly erősen sugározzák a beléjük foglalt mágikus hatást, hogy velük szemben mágiaellenállásnak helye nincs.\n\nA mentálbélyegek viselőjüket az adott mentálmágia hatása alá helyezik. Transzban az áldozat testére kell festeni, de letörölhető. Annyi manna, amennyibe az adott mentál varázslat 20 E erősség esetén kerülne.\n\nA mentális operációk közül a kábítás és bénítás mentálbélyegben való elhelyezése nem jelent különösebb nehézséget, ám az olvasással és az írással merőben más a helyzet. Hiszen ilyenkor a varázsló és az áldozat agya között folyamatosan fennálló kapcsolatra van szükség, ami megköveteli, hogy a varázsló testén is legyen egy hasonló, csak néhány vonásában különböző bélyeg, továbbá, hogy az olvasás, írás ideje alatt a varázsló a kapcsolatra összpontosítson.", "source": "Part 14", "requires": [{"school": "mental", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-belyeg-valtozas', 'Változás bélyege', 'jelmagia', 'belyegek', 2, 'complete', 'wrapper', 'Part 14', '{"id": "jel-belyeg-valtozas", "name": "Változás bélyege", "school": "jelmagia", "subgroup": "belyegek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "body"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "wrapper", "baseMp": 0, "factor": 3, "wraps": [{"school": "anyagi", "subgroup": "termeszetes", "label": "Természetes anyagi mágia"}]}, "inputs": [], "effect": "Néhány centiméter átmérőjű jel, a megbélyegzett testén. Hatásukat arra fejtik ki, akinek a testén a varázsló elhelyezi őket. Az alany egészen addig áldozata a bélyeg hordozta mágiának, ameddig az el nem távolíttatik a testéről. A bélyegek oly erősen sugározzák a beléjük foglalt mágikus hatást, hogy velük szemben mágiaellenállásnak helye nincs.\n\nA Változás varázsjel, amelyet személyre, élőlényre írnak. Ereje nem végtelen, a mozaik erejével egyezik meg, háromszoros mannaáron.", "source": "Part 14", "requires": [{"school": "anyagi", "tier": 3}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-belyeg-lelekcsapda', 'Lélekcsapda bélyeg', 'jelmagia', 'belyegek', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-belyeg-lelekcsapda", "name": "Lélekcsapda bélyeg", "school": "jelmagia", "subgroup": "belyegek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "body"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "flat", "baseMp": 39}, "inputs": [], "effect": "Néhány centiméter átmérőjű jel, a megbélyegzett testén. Hatásukat arra fejtik ki, akinek a testén a varázsló elhelyezi őket. Az alany egészen addig áldozata a bélyeg hordozta mágiának, ameddig az el nem távolíttatik a testéről. A bélyegek oly erősen sugározzák a beléjük foglalt mágikus hatást, hogy velük szemben mágiaellenállásnak helye nincs.\n\nLásd: Nekromancia.", "source": "Part 14", "requires": [{"school": "nekromancia", "tier": 2}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-belyeg-halottmozgatas', 'Halottmozgatás bélyege', 'jelmagia', 'belyegek', 2, 'complete', 'flat', 'Part 14', '{"id": "jel-belyeg-halottmozgatas", "name": "Halottmozgatás bélyege", "school": "jelmagia", "subgroup": "belyegek", "tier": 2, "status": {"state": "complete", "missing": []}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "body"}, "resistance": {"kind": "none"}, "power": null, "cost": {"pattern": "flat", "baseMp": 52}, "inputs": [], "effect": "Néhány centiméter átmérőjű jel, a megbélyegzett testén. Hatásukat arra fejtik ki, akinek a testén a varázsló elhelyezi őket. Az alany egészen addig áldozata a bélyeg hordozta mágiának, ameddig az el nem távolíttatik a testéről. A bélyegek oly erősen sugározzák a beléjük foglalt mágikus hatást, hogy velük szemben mágiaellenállásnak helye nincs.\n\nLásd: Nekromancia.", "source": "Part 14", "requires": [{"school": "nekromancia", "tier": 3}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-belyeg-felruhazas', 'Felruházás bélyege', 'jelmagia', 'belyegek', 2, 'incomplete', 'undefined', 'Part 14', '{"id": "jel-belyeg-felruhazas", "name": "Felruházás bélyege", "school": "jelmagia", "subgroup": "belyegek", "tier": 2, "status": {"state": "incomplete", "missing": ["cost"]}, "castingTime": {"label": "drawing", "time": {"kind": "time", "amounts": {"perc": 5}}}, "duration": {"kind": "untilBroken"}, "range": {"kind": "body"}, "resistance": {"kind": "none"}, "power": {"unit": "E", "baseE": null, "step": null, "infinite": true}, "cost": {"pattern": "undefined"}, "inputs": [{"id": "kind", "label": "Fajta", "type": "choice", "values": ["ertelem", "tudat", "szemelyiseg"], "labels": {"ertelem": "Értelemmel felruházás", "tudat": "Tudattal felruházás", "szemelyiseg": "Személyiséggel felruházás"}}], "effect": "Néhány centiméter átmérőjű jel, a megbélyegzett testén. Hatásukat arra fejtik ki, akinek a testén a varázsló elhelyezi őket. Az alany egészen addig áldozata a bélyeg hordozta mágiának, ameddig az el nem távolíttatik a testéről. A bélyegek oly erősen sugározzák a beléjük foglalt mágikus hatást, hogy velük szemben mágiaellenállásnak helye nincs.\n\nHárom fajtája ismeretes: értelemmel, tudattal, személyiséggel felruházás, ahogy a boszorkánymesteri varázslatoknál érvényesül.", "source": "Part 14", "requires": [{"school": "nekromancia", "tier": 3}]}'::jsonb);
INSERT INTO mosaics (id, name, school, subgroup, tier, status_state, cost_pattern, source, definition) VALUES ('jel-pentagramma-idezo', 'Idéző pentagramma', 'jelmagia', 'pentagrammak', 2, 'incomplete', 'undefined', 'Part 14', '{"id": "jel-pentagramma-idezo", "name": "Idéző pentagramma", "school": "jelmagia", "subgroup": "pentagrammak", "tier": 2, "status": {"state": "incomplete", "missing": ["cost", "castingTime", "duration", "resistance", "power"]}, "castingTime": {"label": "drawing", "time": {"kind": "undefined"}}, "duration": {"kind": "undefined"}, "range": {"kind": "pentagram"}, "resistance": {"kind": "undefined"}, "power": null, "cost": {"pattern": "undefined"}, "inputs": [], "effect": "A pentagramma ötágú csillag, melyet a varázsló olykor csúcsait érintő körbe foglal. Méretére jellemző, hogy ennek a körnek – akár létezik, akár csak képzeletbeli – legalább egy lépésnyi átmérőjűnek kell lennie.", "source": "Part 14", "requires": [{"school": "nekromancia", "tier": 2}]}'::jsonb);
